1	/* ============================ Tự khám phá: mô hình dù lượn ============================
2	   Một Mesh duy nhất (cánh vòm in cờ đỏ sao vàng + dây + người treo + dải đèn mép cánh), gộp bằng mergeGeometries, vertex color nhân với atlas canvas.
3	   Hệ cục bộ: +X là hướng bay, +Y lên, +Z bên phải. Atlas: phần trên là mặt cánh, dải dưới là màu trơn; emissiveMap cùng bố cục, cường độ đọc shared.uNight.
4	   Mọi thông số nằm ở CONFIG.explore.glider (span, lines = khoảng treo, lineCount, chord, arch, segs). */
5	import * as THREE from 'three';
6	import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
7	import { CONFIG } from '../config';
8	import { shared } from '../core/shared';
9	import type { GliderState } from './flight';
10	
11	const G = CONFIG.explore.glider;
12	const UV_DARK = 0.25, UV_LIT = 0.75;         // u trong dải màu trơn: nửa tối / nửa sáng
13	const TILT = Math.tan(G.tilt);               // độ dốc cánh theo hướng bay (mép sau thấp hơn)
14	const ATLAS_W = 1024, ATLAS_H = 256;         // điểm ảnh atlas
15	const WING_H = 216, BAND_Y = 224;            // mặt cánh chiếm y 0..WING_H; dải màu trơn từ BAND_Y tới đáy; khoảng giữa để đệm
16	const V_SOLID = 1 - (BAND_Y + ATLAS_H) / 2 / ATLAS_H, V_WING0 = 1 - WING_H / ATLAS_H;   // v giữa dải màu trơn; v của mép sau cánh
17	
18	/* Gán uv và màu đỉnh cho hình học không chỉ số */
19	function exPaint(g: THREE.BufferGeometry, rgb: number[], u: number): THREE.BufferGeometry {
20	  const n = g.attributes.position.count, col = new Float32Array(n * 3), uv = new Float32Array(n * 2);
21	  for (let i = 0; i < n; i++) { col.set(rgb, i * 3); uv[i * 2] = u; uv[i * 2 + 1] = V_SOLID; }
22	  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
23	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
24	  return g;
25	}
26	
27	/* Dải cánh vòm giữa hai mặt cắt: lệch x0..x1 theo hướng bay, cong xuống ở hai đầu */
28	function exWingStrip(chord0: number, chord1: number, rgb: number[], u: number, lift: number): THREE.BufferGeometry {
29	  const pos: number[] = [];
30	  const half = G.span / 2;
31	  for (let i = 0; i < G.segs; i++) {
32	    const ta = -1 + 2 * i / G.segs, tb = -1 + 2 * (i + 1) / G.segs;
33	    const pa = (t: number, x: number) => [x, -G.arch * half * t * t + lift + x * TILT, t * half];
34	    const a0 = pa(ta, chord0), a1 = pa(ta, chord1), b0 = pa(tb, chord0), b1 = pa(tb, chord1);
35	    pos.push(...a0, ...b0, ...a1, ...a1, ...b0, ...b1);
36	  }
37	  const g = new THREE.BufferGeometry();
38	  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
39	  g.computeVertexNormals();
40	  return exPaint(g, rgb, u);
41	}
42	
43	/* Điểm theo hệ người treo: y tính từ móc treo (−G.lines) */
44	const exP = (x: number, y: number, z: number) => new THREE.Vector3(x, y - G.lines, z);
45	
46	/* Khối bo tròn nối hai điểm (tay, chân, thân) */
47	function exLimb(a: THREE.Vector3, b: THREE.Vector3, r: number, rgb: number[]): THREE.BufferGeometry {
48	  const d = b.clone().sub(a), len = d.length();
49	  const g = new THREE.CapsuleGeometry(r, len, 3, 8).toNonIndexed();
50	  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize()));
51	  g.translate((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2);
52	  return exPaint(g, rgb, UV_DARK);
53	}
54	
55	/* Khối elip tại c, bán trục s */
56	function exBlob(c: THREE.Vector3, s: number[], rgb: number[]): THREE.BufferGeometry {
57	  const g = new THREE.SphereGeometry(1, 12, 8).toNonIndexed();
58	  g.scale(s[0], s[1], s[2]); g.translate(c.x, c.y, c.z);
59	  return exPaint(g, rgb, UV_DARK);
60	}
61	
62	/* Người ngồi trong ghế dù, ngả nhẹ ra sau, chân duỗi về trước, tay cầm dây phanh */
63	function exHuman(parts: THREE.BufferGeometry[]): void {
64	  const JACKET = [0.16, 0.3, 0.55], PANTS = [0.12, 0.13, 0.17], SEAT = [0.05, 0.05, 0.07], BOOT = [0.3, 0.17, 0.08], SKIN = [0.86, 0.66, 0.5], HELMET = [0.92, 0.92, 0.9], VISOR = [0.05, 0.06, 0.1];
65	  parts.push(exBlob(exP(-0.22, -0.68, 0), [0.32, 0.2, 0.3], SEAT));                  // ghế dù
66	  parts.push(exBlob(exP(-0.36, -0.28, 0), [0.14, 0.32, 0.26], SEAT));                // lưng ghế, túi dù dự phòng
67	  parts.push(exLimb(exP(-0.08, -0.62, 0), exP(-0.16, -0.12, 0), 0.19, JACKET));      // thân
68	  for (const z of [-1, 1]) {
69	    parts.push(exLimb(exP(0, 0, z * 0.2), exP(-0.12, -0.3, z * 0.22), 0.025, SEAT));  // đai treo từ móc xuống vai
70	    parts.push(exLimb(exP(-0.04, -0.68, z * 0.13), exP(0.4, -0.7, z * 0.17), 0.085, PANTS));   // đùi
71	    parts.push(exLimb(exP(0.4, -0.7, z * 0.17), exP(0.58, -1.08, z * 0.17), 0.065, PANTS));    // cẳng chân
72	    parts.push(exBlob(exP(0.65, -1.14, z * 0.17), [0.14, 0.06, 0.07], BOOT));         // giày
73	    parts.push(exLimb(exP(-0.14, -0.12, z * 0.24), exP(-0.06, -0.08, z * 0.46), 0.06, JACKET));  // cánh tay
74	    parts.push(exLimb(exP(-0.06, -0.08, z * 0.46), exP(0.02, 0.3, z * 0.34), 0.05, JACKET));     // cẳng tay giơ lên
75	    parts.push(exBlob(exP(0.02, 0.34, z * 0.34), [0.05, 0.06, 0.05], SKIN));          // bàn tay
76	  }
77	  parts.push(exBlob(exP(-0.14, 0.17, 0), [0.12, 0.13, 0.11], SKIN));                  // đầu
78	  parts.push(exBlob(exP(-0.16, 0.22, 0), [0.15, 0.13, 0.135], HELMET));               // mũ bảo hiểm
79	  parts.push(exBlob(exP(-0.05, 0.17, 0), [0.05, 0.035, 0.09], VISOR));                // kính
80	}
81	
82	/* Trải mặt cánh lên atlas: u theo sải, v theo dây cung (mép trước ở đỉnh ảnh, nên đỉnh sao hướng về mép trước) */
83	function exWingUv(g: THREE.BufferGeometry): THREE.BufferGeometry {
84	  const p = g.attributes.position, uv = g.attributes.uv as THREE.BufferAttribute;
85	  for (let i = 0; i < p.count; i++) uv.setXY(i, (p.getZ(i) / G.span + 0.5), V_WING0 + (1 - V_WING0) * (p.getX(i) / G.chord + 0.5));
86	  return g;
87	}
88	
89	/* Hộp mảnh nối hai điểm (dây treo) */
90	function exLine(a: THREE.Vector3, b: THREE.Vector3): THREE.BufferGeometry {
91	  const d = b.clone().sub(a), len = d.length();
92	  const g = new THREE.BoxGeometry(0.03, len, 0.03).toNonIndexed();
93	  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize()));
94	  g.translate((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2);
95	  g.deleteAttribute('uv');
96	  return exPaint(g, [0.15, 0.15, 0.15], UV_DARK);
97	}
98	
99	/* Vẽ mặt cánh: nền đỏ, sao vàng 5 cánh một đỉnh hướng lên, đường ô khí. Tính theo mét nên sao không méo. glow: bản phát sáng ban đêm, tối hơn */
100	function exDrawWing(x: CanvasRenderingContext2D, glow: boolean, wingColor?: string): void {
101	  const sx = ATLAS_W / G.span, sy = WING_H / G.chord, cx = ATLAS_W / 2, cy = WING_H / 2;
102	  x.fillStyle = wingColor ?? G.flagRed; x.fillRect(0, 0, ATLAS_W, BAND_Y);
103	  if (!wingColor) {   // dù của mình: cờ đỏ sao vàng; dù người khác chỉ có nền màu
104	    x.beginPath();
105	    for (let i = 0; i < 10; i++) {
106	      const r = G.starRadius * (i % 2 ? 0.382 : 1), a = -Math.PI / 2 + i * Math.PI / 5;
107	      x.lineTo(cx + Math.cos(a) * r * sx, cy + Math.sin(a) * r * sy);
108	    }
109	    x.closePath(); x.fillStyle = G.flagStar; x.fill();
110	  }
111	  x.fillStyle = 'rgba(70,0,0,0.28)';
112	  for (let i = 0; i <= G.cells; i++) x.fillRect(i * ATLAS_W / G.cells - 1, 0, 2, WING_H);
113	  x.fillStyle = 'rgba(70,0,0,0.12)';
114	  for (const k of [0.3, 0.65]) x.fillRect(0, WING_H * k - 1, ATLAS_W, 2);
115	  if (glow) { x.fillStyle = 'rgba(0,0,0,0.62)'; x.fillRect(0, 0, ATLAS_W, BAND_Y); }
116	}
117	
118	function exAtlasTexture(c: HTMLCanvasElement): THREE.CanvasTexture {
119	  const t = new THREE.CanvasTexture(c);
120	  t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4;
121	  return t;
122	}
123	
124	/* Màu cánh: mặt cánh + dải trơn trắng (nhân với vertex color) */
125	function exColorMap(wingColor?: string): THREE.CanvasTexture {
126	  const c = document.createElement('canvas'); c.width = ATLAS_W; c.height = ATLAS_H;
127	  const x = c.getContext('2d')!;
128	  exDrawWing(x, false, wingColor);
129	  x.fillStyle = '#fff'; x.fillRect(0, BAND_Y, ATLAS_W, ATLAS_H - BAND_Y);
130	  return exAtlasTexture(c);
131	}
132	
133	/* Phát sáng ban đêm: cánh sáng dịu để vẫn thấy cờ; dải trơn nửa trái đen, nửa phải trắng */
134	function exGlowMap(wingColor?: string): THREE.CanvasTexture {
135	  const c = document.createElement('canvas'); c.width = ATLAS_W; c.height = ATLAS_H;
136	  const x = c.getContext('2d')!;
137	  exDrawWing(x, true, wingColor);
138	  x.fillStyle = '#000'; x.fillRect(0, BAND_Y, ATLAS_W / 2, ATLAS_H - BAND_Y);
139	  x.fillStyle = '#fff'; x.fillRect(ATLAS_W / 2, BAND_Y, ATLAS_W / 2, ATLAS_H - BAND_Y);
140	  return exAtlasTexture(c);
141	}
142	
143	/* Hình học dùng chung mọi dù (dựng một lần); vật liệu và texture riêng theo màu */
144	let exGeo: THREE.BufferGeometry | null = null;
145	const exMaps = new Map<string, { map: THREE.CanvasTexture; glow: THREE.CanvasTexture }>();
146	
147	function exGliderGeometry(): THREE.BufferGeometry {
148	  if (exGeo) return exGeo;
149	  const parts: THREE.BufferGeometry[] = [];
150	  /* Cánh: mặt chính + dải đèn hai mép (nhô nhẹ lên trên mặt cánh) */
151	  const body = exWingUv(exWingStrip(-G.chord / 2, G.chord / 2, [1, 1, 1], UV_DARK, 0));
152	  parts.push(body);
153	  parts.push(exWingStrip(G.chord / 2 - 0.12, G.chord / 2, [1, 0.42, 0.38], UV_LIT, 0.02));
154	  parts.push(exWingStrip(-G.chord / 2, -G.chord / 2 + 0.12, [0.75, 0.1, 0.08], UV_LIT, 0.02));   // mép sau: thấy rõ từ camera bám đuôi
155	  /* Người treo, cách cánh G.lines mét */
156	  exHuman(parts);
157	  /* Dây: G.lineCount dây mỗi bên, từ cánh xuống vai */
158	  const half = G.span / 2;
159	  for (const side of [-1, 1]) {
160	    for (let i = 0; i < G.lineCount; i++) {
161	      const t = 0.12 + 0.75 * i / Math.max(1, G.lineCount - 1);
162	      const x = (i % 2 ? 0.5 : -0.5) * G.chord * 0.6;
163	      parts.push(exLine(new THREE.Vector3(x, -G.arch * half * t * t + x * TILT, side * t * half), new THREE.Vector3(0, -G.lines, side * 0.2)));
164	    }
165	  }
166	  const geo = mergeGeometries(parts)!;
167	  /* Gốc group nằm giữa cánh (trên) và người (dưới): cánh ở +lines·k, người ở −lines·(1−k) */
168	  geo.translate(0, G.lines * G.originAt, 0);
169	  return exGeo = geo;
170	}
171	
172	/* wingColor bỏ trống: dù cờ đỏ sao vàng của mình. Có wingColor: nền màu đó, không sao, giữ đường ô khí (dù người khác) */
173	export function exBuildGlider(wingColor?: string): THREE.Group {
174	  const geo = exGliderGeometry();
175	  const key = wingColor ?? '';
176	  let tex = exMaps.get(key);
177	  if (!tex) exMaps.set(key, tex = { map: exColorMap(wingColor), glow: exGlowMap(wingColor) });
178	  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, map: tex.map, roughness: G.roughness, side: THREE.DoubleSide, emissive: 0xffffff, emissiveMap: tex.glow, emissiveIntensity: 0 });
179	  const mesh = new THREE.Mesh(geo, mat);
180	  mesh.castShadow = false; mesh.receiveShadow = false; mesh.frustumCulled = false;
181	  const g = new THREE.Group(); g.name = 'ex-glider'; g.add(mesh);
182	  return g;
183	}
184	
185	/* Đặt dù theo trạng thái bay: quay yaw trước, rồi cuộn quanh trục bay (bank > 0: nghiêng trái, cánh trái hạ) */
186	export function exPlaceGlider(g: THREE.Group, s: GliderState): void {
187	  g.position.copy(s.pos);
188	  g.rotation.set(-s.bank, s.yaw, 0, 'YXZ');
189	  const m = (g.children[0] as THREE.Mesh).material as THREE.MeshStandardMaterial;
190	  m.emissiveIntensity = shared.uNight.value;
191	}
