/* ============================ Tự khám phá: mô hình bay dù lượn ============================
   Thuần toán học, không đụng cảnh. Hướng bay (cos yaw, 0, −sin yaw), cùng quy ước với `walk` trong views/camera.ts:
   yaw tăng là rẽ trái, bank > 0 là nghiêng trái. Mọi thông số ở CONFIG.explore. */
import * as THREE from 'three';
import { CONFIG } from '../config';

const C = CONFIG.explore;

export interface GliderState { pos: THREE.Vector3; yaw: number; bank: number; ret: number; speed: number }   // ret: chiều rẽ đang chốt khi lái về khung (0 = không)
export interface GliderInput { turn: -1 | 0 | 1; climb: -1 | 0 | 1; throttle?: -1 | 0 | 1 }   // throttle: E tăng tốc, Q giảm tốc; bỏ trống = giữ tốc độ

/* Trạng thái ban đầu tại điểm cất cánh */
export function exCreate(): GliderState {
  return { pos: new THREE.Vector3(C.takeoff[0], C.takeoff[1], C.takeoff[2]), yaw: C.takeoffYaw, bank: 0, ret: 0, speed: C.speed };
}

const wrapPi = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));

/* Lái về trong khung khi sát mép. "Hướng vào" n = tổng pháp tuyến hướng vào của các mép nằm trong returnMargin, trọng số theo độ gần.
   Đang bay ra (hướng bay · n < returnEngage) thì bỏ qua phím và lái cố định về n tới khi hướng bay · n >= returnRelease (trễ, hướng rẽ chốt trong s.ret nên không đổi dấu liên tục).
   Chiều rẽ: theo phím người chơi nếu đủ xa mép (vòng tròn bán kính ≈ speed/turnRate không đi ra quá ~2 bán kính, nên giữ A/D chỉ quay tại chỗ, không rung), sát mép (< returnShort) thì rẽ đường ngắn. */
function exTurnEff(s: GliderState, turn: number): number {
  const b = C.bounds, m = C.returnMargin;
  const dx0 = s.pos.x - b.x0, dx1 = b.x1 - s.pos.x, dz0 = s.pos.z - b.z0, dz1 = b.z1 - s.pos.z;
  const d = Math.min(dx0, dx1, dz0, dz1);   // khoảng cách ngắn nhất tới mép khung
  if (d >= m) { s.ret = 0; return turn; }
  const nx = (dx0 < m ? 1 - dx0 / m : 0) - (dx1 < m ? 1 - dx1 / m : 0);   // +X là vào trong khi gần mép x0
  const nz = (dz0 < m ? 1 - dz0 / m : 0) - (dz1 < m ? 1 - dz1 / m : 0);
  const nl = Math.hypot(nx, nz) || 1;
  const dot = (Math.cos(s.yaw) * nx - Math.sin(s.yaw) * nz) / nl;   // hướng bay · hướng vào
  if (s.ret !== 0) { if (dot >= C.returnRelease) { s.ret = 0; return turn; } return s.ret; }
  else if (dot >= C.returnEngage) return turn;
  else {
    const delta = wrapPi(Math.atan2(-nz, nx) - s.yaw);   // yaw hướng vào − yaw hiện tại (>0: rẽ trái là đường ngắn)
    s.ret = turn !== 0 && d >= C.returnShort ? turn : (delta >= 0 ? 1 : -1);
  }
  return s.ret;
}

/* Một bước mô phỏng: không cấp phát */
export function exStep(s: GliderState, inp: GliderInput, dt: number): void {
  s.speed = Math.min(C.speedMax, Math.max(C.speedMin, s.speed + (inp.throttle ?? 0) * C.speedAccel * dt));
  const turn = exTurnEff(s, inp.turn);
  const sharpen = s.ret !== 0 ? Math.max(1, s.speed / C.returnTurnSpeed) : 1;   // đang tự lái về: bay nhanh vẫn giữ bán kính vòng về, không lao vào mép
  s.bank += (turn * C.bankMax - s.bank) * Math.min(1, C.bankRate * sharpen * dt);
  s.yaw += C.turnRate * sharpen * (s.bank / C.bankMax) * dt;
  s.pos.x += Math.cos(s.yaw) * s.speed * dt;
  s.pos.z -= Math.sin(s.yaw) * s.speed * dt;
  s.pos.y = Math.min(C.ceiling, Math.max(C.floor, s.pos.y + inp.climb * C.climbRate * dt));
  const b = C.bounds;   // kẹp cứng: không bao giờ vượt khung
  s.pos.x = Math.min(b.x1, Math.max(b.x0, s.pos.x));
  s.pos.z = Math.min(b.z1, Math.max(b.z0, s.pos.z));
}

/* Phím giữ → đầu vào lái: A/← trái, D/→ phải, W/↑ lên, S/↓ xuống, E tăng tốc, Q giảm tốc; hai phím ngược nhau triệt tiêu */
export function exInputFromKeys(keys: Set<string>, out: GliderInput = { turn: 0, climb: 0, throttle: 0 }): GliderInput {   // out: đối tượng tái dùng cho đường khung hình (không cấp phát)
  const turn = (keys.has('a') || keys.has('arrowleft') ? 1 : 0) - (keys.has('d') || keys.has('arrowright') ? 1 : 0);
  const climb = (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0);
  out.turn = turn as -1 | 0 | 1; out.climb = climb as -1 | 0 | 1; out.throttle = ((keys.has('e') ? 1 : 0) - (keys.has('q') ? 1 : 0)) as -1 | 0 | 1;
  return out;
}
/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
import * as THREE from 'three';
import { scene, camera, controls } from '../core/renderer';
import { cam, keys } from '../views/state';
import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
import { exBuildGlider, exPlaceGlider } from './glider';
import { exChase } from './chase';
import { exShowChooser } from './chooser';
import { exNight, exNightBind, exNightStep } from './nightShows';
import { exMulti } from './multi';
import { stroll, setupStroll } from './stroll';
import { drive, setupDrive } from './drive';
import { stAvatars } from './stroll/avatars';
import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
import { CONFIG } from '../config';
import type { SwingController } from '../bridges/song-han/SwingController';

const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung

let glider: THREE.Group | null = null;
let state: GliderState | null = null;
let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi

const active = () => cam.mode === 'glider' && state !== null;
const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem

/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
function watchStep(dt: number): void {
  exMulti.update(dt, performance.now(), null);
  const st = exMulti.watchState();
  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
  exNightStep(dt);
}

/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
function onMultiChange(): void {
  const s = exMulti.session; if (!s) return;
  if (watching) {
    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
    exWatchRender();
  } else if (active()) {
    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
  }
}

/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
function exShowSpeed(): void {
  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
  if (t === readout) return;
  readout = t;
  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
}

/* Một bước: mô phỏng, đặt dù, đặt camera bám */
function advance(dt: number, inp: GliderInput): void {
  exStep(state!, inp, dt);
  exPlaceGlider(glider!, state!);
  exChase(camera, controls.target, state!, dt);
  exShowSpeed();
  exNightStep(dt);
  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
}

export const explore = {
  active,
  nightShows: exNight,
  get state() { return state; },
  get glider() { return glider; },
  get watching() { return watching; },
  start(): void {
    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
    exMulti.onChange = onMultiChange;
    state = exCreate();
    const slot = exMulti.session ? exMulti.session.mySlot : -1;
    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
    if (!glider) glider = exBuildGlider();
    if (!glider.parent) scene.add(glider);
    glider.visible = true;
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    exPlaceGlider(glider, state);
    exChase(camera, controls.target, state, 0, true);
    exShowSpeed();
    document.body.classList.add('explore');
  },
  /* Chế độ xem: cam.mode = 'glider' nhưng không có state/dù của mình; carry = true khi vừa nhường chỗ (camera đang ở sau dù cũ) */
  startWatching(carry = false): void {
    const s = exMulti.session; if (!s) return;
    watching = true; chased = carry;
    keys.clear();
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    document.body.classList.add('explore', 'ex-watching');
    exMulti.onChange = onMultiChange;
    exWatchShow(s);
  },
  update(dt: number): void {
    if (watching) { watchStep(dt); return; }
    if (!active()) return;
    advance(dt, exInputFromKeys(keys, _inp));
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
  step(dt: number, inp: GliderInput): void {
    if (active()) advance(dt, inp);
  },
  exit(): void {
    drive.stop();   // lái xe: trả hầm / lớp body / xe trước khi tải lại
    const u = new URL(location.href);
    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
    else location.replace(u.toString());
  },
};

export function setupExplore(ctrl: SwingController): void {
  exNightBind(ctrl);
  setupStroll(ctrl, () => explore.exit());
  setupDrive(ctrl, () => explore.exit());
  window.addEventListener('keydown', (e) => {
    if (!inGlider() && !stroll.inMode() && !drive.inMode()) return;
    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn (bay dù, đi dạo, lái xe và hai chế độ xem)
    if (watching || stroll.inMode() || drive.inMode()) return;   // xem: không lái; đi dạo / lái xe: phím do stroll/index.ts, drive/index.ts ghi
    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
    const t = e.target as HTMLElement | null;
    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
    const k = e.key.toLowerCase(); keys.add(k);
    if (k.startsWith('arrow')) e.preventDefault();
  });
  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
  for (const id of ['langSelect', 'qualitySel']) {
    const sel = document.getElementById(id); if (!sel) continue;
    let byMouse = false;
    sel.addEventListener('pointerdown', () => { byMouse = true; });
    sel.addEventListener('keydown', () => { byMouse = false; });
    sel.addEventListener('change', () => { if (byMouse && (active() || stroll.active() || drive.active())) sel.blur(); byMouse = false; });
  }
  const q = new URLSearchParams(location.search);
  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
  if (q.get('explore') === 'glider') { explore.start(); return; }
  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình, không qua slot
  if (q.get('explore') === 'drive') { drive.start(); return; }   // lái xe một mình
  if (!q.has('test') || q.has('chooser')) {
    document.querySelector('button[data-pick="walk"]')?.addEventListener('click', () => stAvatars.preload(0));   // chọn thẻ Đi dạo: nạp nhân vật của mình ngay, trong lúc ở sảnh
    document.querySelector('button[data-pick="car"]')?.addEventListener('click', () => drive.preload());   // chọn thẻ Ô tô: nạp mô hình xe ngay
    exShowChooser((choice) => { if (choice === 'glider') explore.start(); else if (choice === 'walk') stroll.start(); else if (choice === 'car') drive.start(); },
      (choice) => { if (choice === 'walk') stroll.startWatching(); else if (choice === 'car') drive.startWatching(); else explore.startWatching(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
  }
}
/* ============================ Tự khám phá: camera bám đuôi ============================
   Camera đích = pos − forward·back + up·up; trễ mũ theo CONFIG.explore.chase.lag; nhìn vào pos + forward·look. */
import * as THREE from 'three';
import { CONFIG } from '../config';
import type { GliderState } from './flight';

const K = CONFIG.explore.chase;
const _want = new THREE.Vector3();

export function exChase(camera: THREE.PerspectiveCamera, target: THREE.Vector3, s: GliderState, dt: number, snap = false): void {
  const fx = Math.cos(s.yaw), fz = -Math.sin(s.yaw);
  _want.set(s.pos.x - fx * K.back, s.pos.y + K.up, s.pos.z - fz * K.back);
  if (snap) camera.position.copy(_want);
  else camera.position.lerp(_want, 1 - Math.exp(-dt / (K.lag * Math.min(1, K.lagSpeed / s.speed))));   // khoảng tụt ≈ tốc độ × trễ: bay nhanh giảm trễ để giữ khung hình
  target.set(s.pos.x + fx * K.look, s.pos.y - K.lookDown, s.pos.z + fz * K.look);
  camera.lookAt(target);
}
/* ===== Đi dạo: nạp mô hình người có xương (public/people/p<k>.glb) và một nhân vật đang diễn =====
   - stRigLoad(k): import() động GLTFLoader + SkeletonUtils (chunk riêng, trang thường không tải), nạp p<k>.glb một lần, nhớ đệm theo k.
     Lỗi bất kỳ (mạng, file hỏng, thiếu đoạn) → console.warn một lần cho mô hình đó, trả null, không thử lại trong phiên; promise không bao giờ bị từ chối.
   - stRigSource: chuẩn hóa cảnh đã nạp: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng, tắt frustumCulled (hộp bao theo tư thế gốc sai khi diễn),
     vật liệu metalness 0, roughness 0.85; mảnh alpha (alphaMode MASK) giữ alphaTest, không trộn trong suốt. Tốc độ tự nhiên từng đoạn đọc từ extras.speed.
   - Làm nóng: sau khi nạp, stRigLoad chờ hàm do stRigSetWarm gắn (compileAsync theo cảnh chính, ≤ anim.warmMs) rồi mới trả nguồn (D-018).
   - StRig: một bản sao (SkeletonUtils.clone, dùng chung geometry / texture / vật liệu với nguồn) + AnimationMixer riêng.
     pose(): trọng số đích từ stClipMix (anim.ts), làm mượt về đích với hằng thời gian anim.fade; walk / jog / sprint đồng pha bằng một pha chung 0–1
     (đặt action.time = pha × thời lượng đoạn, timeScale 0 để mixer không tự tua); photo LoopOnce + clampWhenFinished, phát lại từ đầu mỗi lần chuyển sang dáng chụp ảnh.
     dt kẹp [0, stroll.dtMax] (tab ẩn rồi quay lại không làm nhảy pha). Không cấp phát mỗi khung (D-018).
   - Mô hình: mét, chân ở y = 0, mặt hướng +X (như hình khối), xương Rocketbox (Bip01_*). docs/superpowers/specs/2026-11-12-nguoi-di-dao-that-design.md §5, §7 */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { ST_CLIPS, stClipMix, type StClipMix } from './anim';

const A = CONFIG.stroll.anim, NC = ST_CLIPS.length;
const ST_LOCO0 = 1, ST_LOCO1 = 3, ST_PHOTO = 4;   // chỉ số trong ST_CLIPS: walk..sprint, photo (idle = 0)

export interface StRigSource {
  scene: THREE.Object3D;                                   // cảnh gốc (không thêm vào scene; chỉ để sao chép)
  clips: THREE.AnimationClip[];                            // 5 đoạn theo thứ tự ST_CLIPS
  natural: Float32Array;                                   // tốc độ tự nhiên từng đoạn theo ST_CLIPS, m/s (idle / photo = 0)
  height: number;                                          // chiều cao tư thế đứng, m (0 nếu file không ghi)
  clone: (o: THREE.Object3D) => THREE.Object3D;            // SkeletonUtils.clone (test truyền bản giả)
}

/* Chuẩn hóa cảnh + đoạn đã nạp thành nguồn dùng chung. speeds: tên đoạn → m/s. Thiếu đoạn nào thì ném lỗi (stRigLoad bắt, trả null) */
export function stRigSource(scene: THREE.Object3D, clips: THREE.AnimationClip[], speeds: Record<string, number>, height: number, clone: (o: THREE.Object3D) => THREE.Object3D): StRigSource {
  const out: THREE.AnimationClip[] = [], natural = new Float32Array(NC);
  for (let i = 0; i < NC; i++) {
    const c = clips.find(x => x.name === ST_CLIPS[i]);
    if (!c) throw new Error(`thiếu đoạn ${ST_CLIPS[i]}`);
    out.push(c);
    natural[i] = Math.max(0, Number(speeds[ST_CLIPS[i]]) || 0);
  }
  scene.traverse((o) => {
    o.layers.set(1);
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false;
    const mats = Array.isArray(m.material) ? m.material : [m.material];
    for (const mat of mats) {
      const s = mat as THREE.MeshStandardMaterial;
      if (s.isMeshStandardMaterial) { s.metalness = 0; s.roughness = 0.85; }
      if (s.alphaTest > 0) s.transparent = false;   // MASK: cắt theo alphaTest, không trộn trong suốt (không cần sắp thứ tự)
    }
  });
  return { scene, clips: out, natural, height: height > 0 ? height : 0, clone };
}

const cache = new Map<number, Promise<StRigSource | null>>();

/* Làm nóng shader (D-018): stroll/index.ts gắn hàm biên dịch sẵn chương trình của cảnh nguồn theo đèn / sương / bóng của cảnh chính
   (rig.ts không import renderer để chạy được trong unit test). Chưa gắn, lỗi hoặc quá anim.warmMs: bỏ qua, nguồn vẫn dùng được */
let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
export function stRigSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
async function stRigWarm(o: THREE.Object3D): Promise<void> {
  if (!warm) return;
  let timer = 0;
  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, A.warmMs) as unknown as number; })]); }
  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch như cũ */ }
  finally { clearTimeout(timer); }
}

/* Nạp mô hình k (nhớ đệm). Không bao giờ ném / từ chối: lỗi → warn một lần, null */
export function stRigLoad(model: number): Promise<StRigSource | null> {
  let p = cache.get(model);
  if (p) return p;
  p = (async () => {
    try {
      const path = A.models[model];
      if (!path) throw new Error('không có mô hình số này');
      const [{ GLTFLoader }, SU] = await Promise.all([import('three/addons/loaders/GLTFLoader.js'), import('three/addons/utils/SkeletonUtils.js')]);
      const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + path);
      const speeds: Record<string, number> = {};
      const json = gltf.parser.json as { animations?: { name?: string; extras?: { speed?: number } }[] };   // AnimationClip không giữ extras: đọc từ JSON gốc
      for (const a of json.animations || []) if (a.name) speeds[a.name] = Number(a.extras?.speed) || 0;
      const src = stRigSource(gltf.scene, gltf.animations, speeds, Number(gltf.scene.userData?.height) || 0, SU.clone);
      await stRigWarm(src.scene);   // nguồn chỉ "sẵn sàng" sau khi shader skinning đã biên dịch: lần hiện đầu không khựng
      return src;
    } catch (e) {
      console.warn(`Đi dạo: không nạp được mô hình người ${model}, dùng hình khối`, e);
      return null;
    }
  })();
  cache.set(model, p);
  return p;
}

/* Một nhân vật đang diễn: bản sao của nguồn + mixer riêng */
export class StRig {
  readonly root: THREE.Object3D;
  readonly src: StRigSource;
  readonly mixer: THREE.AnimationMixer;
  readonly actions: THREE.AnimationAction[] = [];
  readonly w = new Float32Array(NC);    // trọng số đang dùng (đã làm mượt), tổng = 1
  rate = 1;                             // hệ số tua đoạn di chuyển đang dùng
  phase = 0;                            // pha chung 0–1 của walk / jog / sprint
  private readonly mix: StClipMix = { w: new Float32Array(NC), rate: 1, loco: false };
  private fresh = true;                 // lần pose đầu: đặt thẳng trọng số đích, không làm mượt
  private photo = false;                // khung trước đang ở dáng chụp ảnh

  constructor(src: StRigSource) {
    this.src = src;
    this.root = src.clone(src.scene);
    this.root.name = 'stroll-rig';
    this.mixer = new THREE.AnimationMixer(this.root);
    for (let i = 0; i < NC; i++) {
      const a = this.mixer.clipAction(src.clips[i]);
      if (i === ST_PHOTO) { a.setLoop(THREE.LoopOnce, 1); a.clampWhenFinished = true; }
      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.timeScale = 0;   // thời gian do pha chung đặt
      a.enabled = false; a.setEffectiveWeight(0); a.play();
      this.actions.push(a);
    }
  }

  /* Mỗi khung: dáng + tốc độ mặt bằng (m/s) + dt (s) → trọng số, pha, mixer.update */
  pose(pose: number, speed: number, dt: number): void {
    const d = dt > 0 ? (dt < CONFIG.stroll.dtMax ? dt : CONFIG.stroll.dtMax) : 0;   // NaN / âm → 0
    const mix = this.mix, w = this.w, acts = this.actions, clips = this.src.clips;
    stClipMix(pose, speed, this.src.natural, mix);
    const toPhoto = mix.w[ST_PHOTO] === 1;
