217	/* ============================ Tự khám phá: camera bám đuôi ============================
218	   Camera đích = pos − forward·back + up·up; trễ mũ theo CONFIG.explore.chase.lag; nhìn vào pos + forward·look. */
219	import * as THREE from 'three';
220	import { CONFIG } from '../config';
221	import type { GliderState } from './flight';
222	
223	const K = CONFIG.explore.chase;
224	const _want = new THREE.Vector3();
225	
226	export function exChase(camera: THREE.PerspectiveCamera, target: THREE.Vector3, s: GliderState, dt: number, snap = false): void {
227	  const fx = Math.cos(s.yaw), fz = -Math.sin(s.yaw);
228	  _want.set(s.pos.x - fx * K.back, s.pos.y + K.up, s.pos.z - fz * K.back);
229	  if (snap) camera.position.copy(_want);
230	  else camera.position.lerp(_want, 1 - Math.exp(-dt / (K.lag * Math.min(1, K.lagSpeed / s.speed))));   // khoảng tụt ≈ tốc độ × trễ: bay nhanh giảm trễ để giữ khung hình
231	  target.set(s.pos.x + fx * K.look, s.pos.y - K.lookDown, s.pos.z + fz * K.look);
232	  camera.lookAt(target);
233	}
