251	
252	export interface StRigSource {
253	  scene: THREE.Object3D;                                   // cảnh gốc (không thêm vào scene; chỉ để sao chép)
254	  clips: THREE.AnimationClip[];                            // 5 đoạn theo thứ tự ST_CLIPS
255	  natural: Float32Array;                                   // tốc độ tự nhiên từng đoạn theo ST_CLIPS, m/s (idle / photo = 0)
256	  height: number;                                          // chiều cao tư thế đứng, m (0 nếu file không ghi)
257	  clone: (o: THREE.Object3D) => THREE.Object3D;            // SkeletonUtils.clone (test truyền bản giả)
258	}
