260	/* Chuẩn hóa cảnh + đoạn đã nạp thành nguồn dùng chung. speeds: tên đoạn → m/s. Thiếu đoạn nào thì ném lỗi (stRigLoad bắt, trả null) */
261	export function stRigSource(scene: THREE.Object3D, clips: THREE.AnimationClip[], speeds: Record<string, number>, height: number, clone: (o: THREE.Object3D) => THREE.Object3D): StRigSource {
262	  const out: THREE.AnimationClip[] = [], natural = new Float32Array(NC);
263	  for (let i = 0; i < NC; i++) {
264	    const c = clips.find(x => x.name === ST_CLIPS[i]);
265	    if (!c) throw new Error(`thiếu đoạn ${ST_CLIPS[i]}`);
266	    out.push(c);
267	    natural[i] = Math.max(0, Number(speeds[ST_CLIPS[i]]) || 0);
268	  }
269	  scene.traverse((o) => {
270	    o.layers.set(1);
271	    const m = o as THREE.Mesh;
272	    if (!m.isMesh) return;
273	    m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false;
274	    const mats = Array.isArray(m.material) ? m.material : [m.material];
275	    for (const mat of mats) {
276	      const s = mat as THREE.MeshStandardMaterial;
277	      if (s.isMeshStandardMaterial) { s.metalness = 0; s.roughness = 0.85; }
278	      if (s.alphaTest > 0) s.transparent = false;   // MASK: cắt theo alphaTest, không trộn trong suốt (không cần sắp thứ tự)
279	    }
280	  });
281	  return { scene, clips: out, natural, height: height > 0 ? height : 0, clone };
282	}
