286	/* Làm nóng shader (D-018): stroll/index.ts gắn hàm biên dịch sẵn chương trình của cảnh nguồn theo đèn / sương / bóng của cảnh chính
287	   (rig.ts không import renderer để chạy được trong unit test). Chưa gắn, lỗi hoặc quá anim.warmMs: bỏ qua, nguồn vẫn dùng được */
288	let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
289	export function stRigSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
290	async function stRigWarm(o: THREE.Object3D): Promise<void> {
291	  if (!warm) return;
292	  let timer = 0;
293	  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, A.warmMs) as unknown as number; })]); }
294	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch như cũ */ }
295	  finally { clearTimeout(timer); }
296	}
