298	/* Nạp mô hình k (nhớ đệm). Không bao giờ ném / từ chối: lỗi → warn một lần, null */
299	export function stRigLoad(model: number): Promise<StRigSource | null> {
300	  let p = cache.get(model);
301	  if (p) return p;
302	  p = (async () => {
303	    try {
304	      const path = A.models[model];
305	      if (!path) throw new Error('không có mô hình số này');
306	      const [{ GLTFLoader }, SU] = await Promise.all([import('three/addons/loaders/GLTFLoader.js'), import('three/addons/utils/SkeletonUtils.js')]);
307	      const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + path);
308	      const speeds: Record<string, number> = {};
309	      const json = gltf.parser.json as { animations?: { name?: string; extras?: { speed?: number } }[] };   // AnimationClip không giữ extras: đọc từ JSON gốc
310	      for (const a of json.animations || []) if (a.name) speeds[a.name] = Number(a.extras?.speed) || 0;
311	      const src = stRigSource(gltf.scene, gltf.animations, speeds, Number(gltf.scene.userData?.height) || 0, SU.clone);
312	      await stRigWarm(src.scene);   // nguồn chỉ "sẵn sàng" sau khi shader skinning đã biên dịch: lần hiện đầu không khựng
313	      return src;
314	    } catch (e) {
315	      console.warn(`Đi dạo: không nạp được mô hình người ${model}, dùng hình khối`, e);
316	      return null;
317	    }
318	  })();
319	  cache.set(model, p);
320	  return p;
321	}
