323	/* Một nhân vật đang diễn: bản sao của nguồn + mixer riêng */
324	export class StRig {
325	  readonly root: THREE.Object3D;
326	  readonly src: StRigSource;
327	  readonly mixer: THREE.AnimationMixer;
328	  readonly actions: THREE.AnimationAction[] = [];
329	  readonly w = new Float32Array(NC);    // trọng số đang dùng (đã làm mượt), tổng = 1
330	  rate = 1;                             // hệ số tua đoạn di chuyển đang dùng
331	  phase = 0;                            // pha chung 0–1 của walk / jog / sprint
332	  private readonly mix: StClipMix = { w: new Float32Array(NC), rate: 1, loco: false };
333	  private fresh = true;                 // lần pose đầu: đặt thẳng trọng số đích, không làm mượt
334	  private photo = false;                // khung trước đang ở dáng chụp ảnh
335	
336	  constructor(src: StRigSource) {
337	    this.src = src;
338	    this.root = src.clone(src.scene);
339	    this.root.name = 'stroll-rig';
340	    this.mixer = new THREE.AnimationMixer(this.root);
341	    for (let i = 0; i < NC; i++) {
342	      const a = this.mixer.clipAction(src.clips[i]);
343	      if (i === ST_PHOTO) { a.setLoop(THREE.LoopOnce, 1); a.clampWhenFinished = true; }
344	      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.timeScale = 0;   // thời gian do pha chung đặt
345	      a.enabled = false; a.setEffectiveWeight(0); a.play();
346	      this.actions.push(a);
347	    }
348	  }
349	
350	  /* Mỗi khung: dáng + tốc độ mặt bằng (m/s) + dt (s) → trọng số, pha, mixer.update */
351	  pose(pose: number, speed: number, dt: number): void {
352	    const d = dt > 0 ? (dt < CONFIG.stroll.dtMax ? dt : CONFIG.stroll.dtMax) : 0;   // NaN / âm → 0
353	    const mix = this.mix, w = this.w, acts = this.actions, clips = this.src.clips;
354	    stClipMix(pose, speed, this.src.natural, mix);
355	    const toPhoto = mix.w[ST_PHOTO] === 1;
356	    if (toPhoto && !this.photo) acts[ST_PHOTO].reset();   // chuyển sang chụp ảnh: giơ máy lại từ đầu
357	    this.photo = toPhoto;
358	    const k = this.fresh || !(A.fade > 0) ? 1 : 1 - Math.exp(-d / A.fade);   // fade ≤ 0: chuyển tức thì (tránh 0/0 = NaN khi d = 0)
359	    this.fresh = false;
360	    for (let i = 0; i < NC; i++) w[i] += (mix.w[i] - w[i]) * k;
361	    if (mix.loco) this.rate = mix.rate;   // đang rời nhóm di chuyển: giữ nhịp cũ trong lúc mờ dần
362	    let lw = 0, dur = 0;
363	    for (let i = ST_LOCO0; i <= ST_LOCO1; i++) { lw += w[i]; dur += w[i] * clips[i].duration; }
364	    if (lw > 1e-4 && dur > 1e-6) {
365	      const p = this.phase + d * this.rate / (dur / lw);   // chu kỳ của hỗn hợp = trung bình thời lượng theo trọng số
366	      this.phase = p - Math.floor(p);
367	    }
368	    for (let i = 0; i < NC; i++) {
369	      const a = acts[i], on = w[i] > 1e-4;
370	      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.time = this.phase * clips[i].duration;
371	      if (on !== a.enabled) a.enabled = on;   // đoạn không trọng số: mixer bỏ qua, không tính
372	      a.setEffectiveWeight(on ? w[i] : 0);
373	    }
374	    this.mixer.update(d);
375	  }
376	
377	  /* Đặt lại như vừa tạo: lần pose kế đặt thẳng trọng số đích */
378	  reset(): void { this.fresh = true; this.photo = false; this.phase = 0; this.w.fill(0); }
379	
380	  /* Gỡ khỏi nhóm, bỏ mixer, giải phóng skeleton riêng của bản sao (SkeletonUtils.clone tạo skeleton mới cho mỗi SkinnedMesh; renderer cấp boneTexture cho từng cái).
381	     geometry / texture / vật liệu thuộc nguồn dùng chung nên không dispose */
382	  dispose(): void {
383	    this.mixer.stopAllAction();
384	    this.mixer.uncacheRoot(this.root);
385	    this.root.removeFromParent();
386	    const seen = new Set<THREE.Skeleton>();
387	    this.root.traverse((o) => {
388	      const sk = (o as THREE.SkinnedMesh).isSkinnedMesh ? (o as THREE.SkinnedMesh).skeleton : null;
389	      if (sk && !seen.has(sk)) { seen.add(sk); sk.dispose(); }
390	    });
391	  }
392	}
